import { Component, OnInit, ViewChild } from '@angular/core';
import { GovBrTabModule, TabComponent, GovBrDatePickerModule, GovBrInputModule } from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { MyTitleComponent } from '../diversos/my-title/my-title.component';
import { Router } from '@angular/router';
import { MensagemService } from '../../services/mensagem.service';
import { DispositivoService } from '../../services/dispositivo.service';
import { Subscription } from 'rxjs/internal/Subscription';
import { ConsultarNcmComponent } from './consultar-ncm/consultar-ncm.component';
import { ConsultarNbsComponent } from './consultar-nbs/consultar-nbs.component';

@Component({
  selector: 'consultar-ncm-nbs',
  templateUrl: './consultar-ncm-nbs.component.html',
  styleUrl: './consultar-ncm-nbs.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    GovBrTabModule,
    GovBrDatePickerModule,
    GovBrInputModule,
    MyTitleComponent,
    ConsultarNcmComponent,
    ConsultarNbsComponent,
  ],
  providers: [],
})
export class ConsultarNcmNbsComponent implements OnInit {

  form!: FormGroup;
  dataConsulta: Date | null = null;
  ncm: string = '';
  nbs: string = '';

  tipoAtivo: 'ncm' | 'nbs' = 'ncm';

  ncmArmazenado: string = '';
  nbsArmazenado: string = '';

  // Subscriptions dos listeners NCM e NBS (para poder desativar/reativar)
  private ncmListener?: Subscription;
  private nbsListener?: Subscription;

  @ViewChild(ConsultarNcmComponent)
  ncmComponent!: ConsultarNcmComponent;

  @ViewChild(ConsultarNbsComponent)
  nbsComponent!: ConsultarNbsComponent;

  @ViewChild('brTabNcm') brTabNcm!: TabComponent;
  @ViewChild('brTabNbs') brTabNbs!: TabComponent;

  private subscriptions: Subscription = new Subscription();
  dispositivo: string = '';

  constructor(
    private formBuilder: FormBuilder,
    private router: Router,
    private mensagemService: MensagemService,
    private dispositivoService: DispositivoService,
  ) { }

  ngOnInit(): void {
    this.form = this.formBuilder.group({
      dataControl: [new Date(), [Validators.required]],
      ncmControl: [null, []], // Validadores serão definidos dinamicamente
      nbsControl: [null, []],  // Validadores serão definidos dinamicamente
    });
    this.setSubscriptions();
    this.configurarListeners(); // Configura listeners para mudanças nos campos
    this.atualizarValidadores(); // Configura validadores iniciais
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.mensagemService.limpar();
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo: any) => {
        this.dispositivo = dispositivo;
        if (this.dispositivo === 'device-xsmall') {

        } else {

        }
      }));
  }

  // Configura listeners apenas para a data
  configurarListeners() {
    // Listener para mudanças na data - limpa ambos os resultados
    this.subscriptions.add(
      this.form.get('dataControl')?.valueChanges.subscribe(() => {
        this.limparResultados();
      })
    );
  }


  // Limpa os resultados de ambos os componentes filhos
  limparResultados() {
    if (this.ncmComponent) {
      this.ncmComponent.limparResultado();
    }
    if (this.nbsComponent) {
      this.nbsComponent.limparResultado();
    }
  }


  // Limpa apenas o resultado do NCM (chamado quando usuário digita no input NCM)
  limparResultadoNCM() {
    if (this.ncmComponent) {
      this.ncmComponent.limparResultado();
    }
  }


  // Limpa apenas o resultado do NBS (chamado quando usuário digita no input NBS)
  limparResultadoNBS() {
    if (this.nbsComponent) {
      this.nbsComponent.limparResultado();
    }
  }


  // Atualiza os validadores dos campos NCM e NBS conforme o tipo ativo
  atualizarValidadores() {
    const ncmControl = this.form.get('ncmControl');
    const nbsControl = this.form.get('nbsControl');

    if (this.tipoAtivo === 'ncm') {
      // Armazena NBS antes de limpar
      const nbsValue = nbsControl?.value;
      if (nbsValue) {
        this.nbsArmazenado = nbsValue;
      }

      // NCM ativo
      ncmControl?.setValidators([Validators.required, Validators.minLength(8), Validators.maxLength(8)]);
      if (this.ncmArmazenado) {
        ncmControl?.setValue(this.ncmArmazenado, { emitEvent: false });
      }

      // NBS inativo
      nbsControl?.clearValidators();
      nbsControl?.setValue(null, { emitEvent: false });
    } else {
      // Armazena NCM antes de limpar
      const ncmValue = ncmControl?.value;
      if (ncmValue) {
        this.ncmArmazenado = ncmValue;
      }

      // NBS ativo
      nbsControl?.setValidators([Validators.required, Validators.minLength(9), Validators.maxLength(9)]);
      if (this.nbsArmazenado) {
        nbsControl?.setValue(this.nbsArmazenado, { emitEvent: false });
      }

      // NCM inativo
      ncmControl?.clearValidators();
      ncmControl?.setValue(null, { emitEvent: false });
    }

    ncmControl?.updateValueAndValidity();
    nbsControl?.updateValueAndValidity();
  }

  submit(event: any) {
    this.mensagemService.limpar();

    if (!this.form.valid) {
      this.mensagemService.mostrar('Erro', 'Erro', 'Por favor, preencha corretamente o formulário antes de consultar.');
      return;
    }

    this.dataConsulta = this.form.get('dataControl')?.value;

    // Aciona a consulta no componente filho ativo
    if (this.tipoAtivo === 'ncm' && this.ncmComponent && this.brTabNcm.active) {
      this.ncm = this.form.get('ncmControl')?.value;
      this.ncmComponent.consultar(this.dataConsulta, this.ncm);
    } else if (this.tipoAtivo === 'nbs' && this.nbsComponent && this.brTabNbs.active) {
      this.nbs = this.form.get('nbsControl')?.value;
      this.nbsComponent.consultar(this.dataConsulta, this.nbs);
    }
  }

  onTabActiveChange(tab: TabComponent) {
    if (tab === this.brTabNcm) {
      this.tipoAtivo = 'ncm';
    } else if (tab === this.brTabNbs) {
      this.tipoAtivo = 'nbs';
    }

    // Atualiza validadores conforme a tab ativa
    this.atualizarValidadores();
  }

  voltar() {
    this.router.navigate(['/calculadora']);
  }

}
